#include <bits/stdc++.h>
using namespace std;

int fen[100005];

int main() {
    int n;
    long long X1, X2;
    if (scanf("%d %lld %lld", &n, &X1, &X2) != 3) return 0;

    vector<long long> f(n), g(n);
    for (int i = 0; i < n; i++) {
        long long a, b;
        scanf("%lld %lld", &a, &b);
        f[i] = a * X1 + b;   // valor da reta em x = X1
        g[i] = a * X2 + b;   // valor da reta em x = X2
    }

    // A interseção de (i,j) está em [X1,X2]  <=>  (f_i - f_j)*(g_i - g_j) <= 0.
    // Contamos o complemento: pares com f_i < f_j E g_i < g_j (mesma ordem estrita).
    vector<int> idx(n);
    for (int i = 0; i < n; i++) idx[i] = i;
    sort(idx.begin(), idx.end(), [&](int x, int y) {
        if (f[x] != f[y]) return f[x] < f[y];
        return g[x] < g[y];
    });

    vector<long long> vals(g);
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();

    auto upd = [&](int i) { for (; i <= m; i += i & (-i)) fen[i]++; };
    auto qry = [&](int i) { int s = 0; for (; i > 0; i -= i & (-i)) s += fen[i]; return s; };

    long long caseB = 0; // pares a excluir
    int i = 0;
    while (i < n) {
        int j = i;
        while (j < n && f[idx[j]] == f[idx[i]]) j++; // grupo de f igual
        // consulta todos os membros do grupo antes de inseri-los
        for (int t = i; t < j; t++) {
            int r = (int)(lower_bound(vals.begin(), vals.end(), g[idx[t]]) - vals.begin()) + 1;
            caseB += qry(r - 1); // conta g's estritamente menores já inseridas (f estritamente menor)
        }
        for (int t = i; t < j; t++) {
            int r = (int)(lower_bound(vals.begin(), vals.end(), g[idx[t]]) - vals.begin()) + 1;
            upd(r);
        }
        i = j;
    }

    long long total = (long long)n * (n - 1) / 2;
    printf("%lld\n", total - caseB);
    return 0;
}
